  country_rank int2,
  country_type int2,
  ruler int4,
  capital int4,
  market int4,
  market_capital int4,
  power_bloc int4,
  founding_company int4,
  map_color_override int4,
  dynamic_name_key int4,
  dynamic_adjective_key int4,
